/** A side of a page: *amud aleph* (a) or *amud beis* (b). */
enum class Side(val value: Int) {
    /** The front of the page, "a". */
    Aleph(0),
    /** The back of the page, "b". */
    Bet(1);

    companion object {
        /** The variant whose ABI value is [value]. */
        fun fromValue(value: Int): Side = entries.firstOrNull { it.value == value }
            ?: throw NativeBugException(-3, "unknown Side value $value")
    }
}

/** A day's portion of Tehillim. */
sealed class TehillimUnit {
    /** Whole chapters, `start` to `end` inclusive. */
    data class Psalms(
        /** The first chapter. */
        val start: Int,
        /** The last chapter. */
        val end: Int,
    ) : TehillimUnit()
    /** Part of one long chapter (119, split over two days). */
    data class PsalmVerses(
        /** The chapter. */
        val psalm: Int,
        /** The first verse. */
        val start_verse: Int,
        /** The last verse. */
        val end_verse: Int,
    ) : TehillimUnit()
}

internal fun packTehillimUnit(_w: BufferWriter, _v: TehillimUnit) {
    when (_v) {
        is TehillimUnit.Psalms -> {
            _w.writeI32(0)
            _w.writeI32(_v.start)
            _w.writeI32(_v.end)
        }
        is TehillimUnit.PsalmVerses -> {
            _w.writeI32(1)
            _w.writeI32(_v.psalm)
            _w.writeI32(_v.start_verse)
            _w.writeI32(_v.end_verse)
        }
    }
}

internal fun unpackTehillimUnit(_r: BufferReader): TehillimUnit = when (val _tag = _r.readI32()) {
    0 -> TehillimUnit.Psalms(_r.readI32(), _r.readI32())
    1 -> TehillimUnit.PsalmVerses(_r.readI32(), _r.readI32(), _r.readI32())
    else -> throw NativeBugException(-3, "malformed value buffer: unknown TehillimUnit tag $_tag")
}

/** The Pirkei Avos read on a Shabbos afternoon. */
sealed class PirkeiAvosUnit {
    /** One chapter. */
    data class Single(
        /** The chapter, 1 to 6. */
        val chapter: Int,
    ) : PirkeiAvosUnit()
    /** Two chapters read together, at the end of the summer. */
    data class Combined(
        /** The first chapter. */
        val first: Int,
        /** The second chapter. */
        val second: Int,
    ) : PirkeiAvosUnit()
}

internal fun packPirkeiAvosUnit(_w: BufferWriter, _v: PirkeiAvosUnit) {
    when (_v) {
        is PirkeiAvosUnit.Single -> {
            _w.writeI32(0)
            _w.writeI32(_v.chapter)
        }
        is PirkeiAvosUnit.Combined -> {
            _w.writeI32(1)
            _w.writeI32(_v.first)
            _w.writeI32(_v.second)
        }
    }
}

internal fun unpackPirkeiAvosUnit(_r: BufferReader): PirkeiAvosUnit = when (val _tag = _r.readI32()) {
    0 -> PirkeiAvosUnit.Single(_r.readI32())
    1 -> PirkeiAvosUnit.Combined(_r.readI32(), _r.readI32())
    else -> throw NativeBugException(-3, "malformed value buffer: unknown PirkeiAvosUnit tag $_tag")
}

/** A page (*daf*) of the Talmud: both sides of one leaf. */
data class Daf(
    /** The tractate. */
    val tractate: Tractate,
    /** The page number. The Bavli starts at 2, the Yerushalmi at 1. */
    val number: Int,
    /** As text, for example "Bava Metzia 55". */
    val display: String,
)

internal fun packDaf(_w: BufferWriter, _v: Daf) {
    _w.writeI32(_v.tractate.value)
    _w.writeI32(_v.number)
    _w.writeString(_v.display)
}

internal fun unpackDaf(_r: BufferReader): Daf = Daf(
    Tractate.fromValue(_r.readI32()),
    _r.readI32(),
    _r.readString(),
)

/** One side of a page (*amud*). */
data class Amud(
    /** The tractate. */
    val tractate: Tractate,
    /** The page number. */
    val number: Int,
    /** Which side of the page. */
    val side: Side,
    /** As text, for example "Bava Metzia 55b". */
    val display: String,
)

internal fun packAmud(_w: BufferWriter, _v: Amud) {
    _w.writeI32(_v.tractate.value)
    _w.writeI32(_v.number)
    _w.writeI32(_v.side.value)
    _w.writeString(_v.display)
}

internal fun unpackAmud(_r: BufferReader): Amud = Amud(
    Tractate.fromValue(_r.readI32()),
    _r.readI32(),
    Side.fromValue(_r.readI32()),
    _r.readString(),
)

/** One *mishnah*. */
data class Mishna(
    /** The tractate. */
    val tractate: Tractate,
    /** The chapter (*perek*), from 1. */
    val chapter: Int,
    /** The *mishnah* within the chapter, from 1. */
    val number: Int,
    /** As text, for example "Nazir 5:5". */
    val display: String,
)

internal fun packMishna(_w: BufferWriter, _v: Mishna) {
    _w.writeI32(_v.tractate.value)
    _w.writeI32(_v.chapter)
    _w.writeI32(_v.number)
    _w.writeString(_v.display)
}

internal fun unpackMishna(_r: BufferReader): Mishna = Mishna(
    Tractate.fromValue(_r.readI32()),
    _r.readI32(),
    _r.readI32(),
    _r.readString(),
)

/** The two *mishnayos* of a day of Mishna Yomis. */
data class MishnaPair(
    /** The first *mishnah*. */
    val first: Mishna,
    /** The second, the next *mishnah* in order. */
    val second: Mishna,
    /** As text, for example "Nazir 5:5-6". */
    val display: String,
)

internal fun packMishnaPair(_w: BufferWriter, _v: MishnaPair) {
    packMishna(_w, _v.first)
    packMishna(_w, _v.second)
    _w.writeString(_v.display)
}

internal fun unpackMishnaPair(_r: BufferReader): MishnaPair = MishnaPair(
    unpackMishna(_r),
    unpackMishna(_r),
    _r.readString(),
)

/** The Hebrew calendar: dates, holidays, the weekly *parsha*, years and the molad. */
object Calendar {
    /**
     * Facts about the Hebrew year `year`.
     *
     * # Errors
     *
     * `CalendarError::InvalidDate` for a year outside 1 to 9999.
     */
    fun yearInfo(year: Int): YearInfo = decodeBuffer(JniBridge.calendar_year_info(year)) { _r -> unpackYearInfo(_r) }

    /**
     * The number of days in `month` of `year`, or none when the year has no such month or is
     * outside 1 to 9999.
     */
    fun daysInMonth(year: Int, month: HebrewMonth): Int? = decodeBuffer(JniBridge.calendar_days_in_month(year, month.value)) { _r -> unpackOptionalOfI32(_r) }

    /**
     * 1 Tishrei of `year`.
     *
     * # Errors
     *
     * `CalendarError::InvalidDate` for a year outside 1 to 9999.
     */
    fun roshHashana(year: Int): HebrewDate = HebrewDate.fromHandle(JniBridge.calendar_rosh_hashana(year))

    /**
     * The holiday's English name, for example "Chanukah".
     *
     * # Errors
     *
     * `CalendarError::InvalidHoliday` for a day of Chanukah outside 1 to 8, or of the Omer
     * outside 1 to 49.
     */
    fun holidayName(holiday: Holiday): String = decodeUtf8(JniBridge.calendar_holiday_name(encodeBuffer { _w -> packHoliday(_w, holiday) }))

    /**
     * The holiday's Hebrew name.
     *
     * # Errors
     *
     * `CalendarError::InvalidHoliday` for a day of Chanukah outside 1 to 8, or of the Omer
     * outside 1 to 49.
     */
    fun holidayHebrew(holiday: Holiday): String = decodeUtf8(JniBridge.calendar_holiday_hebrew(encodeBuffer { _w -> packHoliday(_w, holiday) }))

    /**
     * Whether melacha is forbidden on the holiday.
     *
     * # Errors
     *
     * `CalendarError::InvalidHoliday` for a day of Chanukah outside 1 to 8, or of the Omer
     * outside 1 to 49.
     */
    fun holidayIsAssurBemelacha(holiday: Holiday): Boolean = JniBridge.calendar_holiday_is_assur_bemelacha(encodeBuffer { _w -> packHoliday(_w, holiday) })

    /**
     * Whether the holiday is a modern Israeli one, such as Yom Ha'atzmaut.
     *
     * # Errors
     *
     * `CalendarError::InvalidHoliday` for a day of Chanukah outside 1 to 8, or of the Omer
     * outside 1 to 49.
     */
    fun holidayIsModern(holiday: Holiday): Boolean = JniBridge.calendar_holiday_is_modern(encodeBuffer { _w -> packHoliday(_w, holiday) })

    /**
     * Whether the holiday is a fast day.
     *
     * # Errors
     *
     * `CalendarError::InvalidHoliday` for a day of Chanukah outside 1 to 8, or of the Omer
     * outside 1 to 49.
     */
    fun holidayIsFastDay(holiday: Holiday): Boolean = JniBridge.calendar_holiday_is_fast_day(encodeBuffer { _w -> packHoliday(_w, holiday) })

    /** The portion's English name, for example "Lech Lecha". */
    fun parshaName(parsha: Parsha): String = decodeUtf8(JniBridge.calendar_parsha_name(parsha.value))

    /** The portion's Hebrew name. */
    fun parshaHebrew(parsha: Parsha): String = decodeUtf8(JniBridge.calendar_parsha_hebrew(parsha.value))

    /** The month's English name, for example "Nisan". */
    fun monthName(month: HebrewMonth): String = decodeUtf8(JniBridge.calendar_month_name(month.value))

    /** The month's Hebrew name. */
    fun monthHebrew(month: HebrewMonth): String = decodeUtf8(JniBridge.calendar_month_hebrew(month.value))

    /**
     * Daily learning schedules: Daf Yomi, Mishna Yomis, Tehillim and the others.
     *
     * Each function gives the portion for a date, or none when nothing is scheduled (before the
     * program began, on Shabbos for a weekly program, outside the Pirkei Avos season).
     */
    object Limudim {
        /** The tractate's English name, for example "Bava Metzia". */
        fun tractateName(tractate: Tractate): String = decodeUtf8(JniBridge.calendar_limudim_tractate_name(tractate.value))

        /** The tractate's Hebrew name. */
        fun tractateHebrew(tractate: Tractate): String = decodeUtf8(JniBridge.calendar_limudim_tractate_hebrew(tractate.value))

        /**
         * The portion as text, for example "Tehillim 1-9".
         *
         * # Errors
         *
         * `LimudimError::InvalidUnit` for a psalm outside 1 to 150 or a verse outside 1 to 176.
         */
        fun tehillimDisplay(unit: TehillimUnit): String = decodeUtf8(JniBridge.calendar_limudim_tehillim_display(encodeBuffer { _w -> packTehillimUnit(_w, unit) }))

        /**
         * The portion as text, for example "Pirkei Avos 5-6".
         *
         * # Errors
         *
         * `LimudimError::InvalidUnit` for a chapter outside 1 to 6.
         */
        fun pirkeiAvosDisplay(unit: PirkeiAvosUnit): String = decodeUtf8(JniBridge.calendar_limudim_pirkei_avos_display(encodeBuffer { _w -> packPirkeiAvosUnit(_w, unit) }))

        /** Daf Yomi: a page of the Babylonian Talmud a day, from 11 September 1923. */
        fun dafYomiBavli(date: HebrewDate): Daf? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_daf_yomi_bavli(_h0)) { _r -> unpackOptionalOfDaf(_r) }
        }

        /** Daf Hashavua: a page of the Babylonian Talmud a week. */
        fun dafHashavuaBavli(date: HebrewDate): Daf? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_daf_hashavua_bavli(_h0)) { _r -> unpackOptionalOfDaf(_r) }
        }

        /** Daf Yomi Yerushalmi: a page of the Jerusalem Talmud a day. */
        fun dafYomiYerushalmi(date: HebrewDate): Daf? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_daf_yomi_yerushalmi(_h0)) { _r -> unpackOptionalOfDaf(_r) }
        }

        /** Dirshu's Amud Yomi: one side of a page of the Babylonian Talmud a day. */
        fun amudYomiDirshu(date: HebrewDate): Amud? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_amud_yomi_dirshu(_h0)) { _r -> unpackOptionalOfAmud(_r) }
        }

        /** Mishna Yomis: two *mishnayos* a day, from 20 May 1947. */
        fun mishnaYomis(date: HebrewDate): MishnaPair? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_mishna_yomis(_h0)) { _r -> unpackOptionalOfMishnaPair(_r) }
        }

        /** Tehillim divided over the days of the Hebrew month. */
        fun tehillimMonthly(date: HebrewDate): TehillimUnit? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_tehillim_monthly(_h0)) { _r -> unpackOptionalOfTehillimUnit(_r) }
        }

        /** Pirkei Avos: a chapter each Shabbos afternoon from Pesach to Rosh Hashana. */
        fun pirkeiAvos(date: HebrewDate, region: Region): PirkeiAvosUnit? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.calendar_limudim_pirkei_avos(_h0, region.value)) { _r -> unpackOptionalOfPirkeiAvosUnit(_r) }
        }
    }
}

